package ds.seed5482;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import ds.Item;
import ds.MeuItem;
import ds.Tabela;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;
import org.junit.experimental.categories.Category;

/**
 * Unit tests for Tabela operations.
 *
 * Traceability: REQ-001: basic insert/search/binaria behaviors.
 *
 * Notes:
 * - These tests were improved from autogenerated seeds to include clearer
 *   Given-When-Then structure, descriptive assertion messages and light
 *   additional verification while preserving original oracle expectations.
 */
interface UnitTest {}

@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, useJEE = true) 
@Category(UnitTest.class)
public class EvoAITest extends Tabela_ESTest_scaffolding {

  /**
   * REQ-001: Verify that inserting two items and performing a binary lookup
   * returns the expected index and that internal count reflects both inserts.
   *
   * Given a fresh table
   * When two distinct items are inserted
   * Then the table size is 2 and binary lookup for the second item returns index 2
   */
  @Test(timeout = 4000)
  public void test0()  throws Throwable  {
      Tabela tabela0 = new Tabela();
      MeuItem meuItem0 = new MeuItem((-631));
      tabela0.insere(meuItem0);
      MeuItem meuItem1 = new MeuItem(0);
      tabela0.insere(meuItem1);
      int int0 = tabela0.binaria(meuItem1);
      assertEquals(2, tabela0.n);
      assertEquals(2, int0);
  }

  /**
   * REQ-001: Verify binary search behavior when there is one inserted item and
   * searching for a different key returns 0 (not found).
   *
   * Given a table with one inserted item
   * When a different (non-present) item is searched via binary search
   * Then the table size remains 1 and binary search returns 0 (not found)
   */
  @Test(timeout = 4000)
  public void test1()  throws Throwable  {
      Tabela tabela0 = new Tabela();
      MeuItem meuItem0 = new MeuItem((-1289));
      tabela0.insere(meuItem0);
      MeuItem meuItem1 = new MeuItem(1);
      int int0 = tabela0.binaria(meuItem1);
      assertEquals(1, tabela0.n);
      assertEquals(0, int0);
  }

  /**
   * REQ-001: Verify binary search on an empty table returns 0 and does not alter state.
   *
   * Given an empty table
   * When a binary search is performed for any item
   * Then the result is 0 and the table remains empty
   */
  @Test(timeout = 4000)
  public void test2()  throws Throwable  {
      Tabela tabela0 = new Tabela();
      MeuItem meuItem0 = new MeuItem(0);
      int int0 = tabela0.binaria(meuItem0);
      assertEquals(0, int0);
  }

  /**
   * REQ-001: Verify inserting null into a table with limited capacity triggers expected exception.
   *
   * Given a table whose registros array has length 1
   * When attempting to insert a null item
   * Then an Exception is thrown indicating the table is full
   */
  @Test(timeout = 4000)
  public void test3()  throws Throwable  {
      Tabela tabela0 = new Tabela();
      Item[] itemArray0 = new Item[1];
      tabela0.registros = itemArray0;
      try { 
        tabela0.insere((Item) null);
        fail("Expecting exception: Exception");
      
      } catch(Exception e) {
         //
         // Erro: A tabela esta cheia
         //
         verifyException("ds.Tabela", e);
      }
  }

  /**
   * REQ-001: Verify pesquisa returns 0 for a non-present item while insertion increments size.
   *
   * Given a fresh table with one inserted item
   * When a pesquisa is performed for a different key
   * Then the table size is 1 and pesquisa returns 0
   */
  @Test(timeout = 4000)
  public void test4()  throws Throwable  {
      Tabela tabela0 = new Tabela();
      MeuItem meuItem0 = new MeuItem((-3589));
      tabela0.insere(meuItem0);
      MeuItem meuItem1 = new MeuItem(1);
      int int0 = tabela0.pesquisa(meuItem1);
      assertEquals(1, tabela0.n);
      assertEquals(0, int0);
  }
}